main {
    width: 100%;
}

.container {
    max-width: 500px;
    width: 100%;
    margin: 0 auto;
    background: #1f1f1f;
    border-radius: 12px;
    padding: 40px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
    border: 1px solid #333;
}

h1 {
    font-size: 28px;
    font-weight: 600;
    margin-bottom: 30px;
    color: #ffffff;
    letter-spacing: -0.5px;
}

form {
    display: flex;
    flex-direction: column;
    gap: 30px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

fieldset {
    border: none;
    padding: 0;
    margin: 0;
}

legend {
    font-size: 16px;
    font-weight: 600;
    color: #ffffff;
    margin-bottom: 16px;
    padding: 0;
    display: block;
}

.radio-option {
    display: flex;
    align-items: center;
    padding: 12px;
    margin-bottom: 8px;
    border-radius: 8px;
    transition: background-color 0.2s ease, border-color 0.2s ease;
    cursor: pointer;
    border: 2px solid transparent;
}

.radio-option:hover {
    background-color: rgba(255, 255, 255, 0.05);
}

input[type="radio"] {
    width: 20px;
    height: 20px;
    margin-right: 12px;
    cursor: pointer;
    accent-color: #4a9eff;
    flex-shrink: 0;
}

input[type="radio"]:focus {
    outline: 2px solid #4a9eff;
    outline-offset: 2px;
}

input[type="radio"]:focus-visible {
    outline: 2px solid #4a9eff;
    outline-offset: 2px;
}

label {
    font-size: 15px;
    color: #e0e0e0;
    cursor: pointer;
    user-select: none;
    display: flex;
    align-items: center;
}

.submit-btn {
    padding: 12px 24px;
    font-size: 16px;
    font-weight: 600;
    background: linear-gradient(135deg, #4a9eff 0%, #357abd 100%);
    color: #ffffff;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.2s ease;
    text-align: center;
    letter-spacing: 0.5px;
    margin-top: 10px;
}

.submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(74, 158, 255, 0.3);
    background: linear-gradient(135deg, #5ba9ff 0%, #3d87cc 100%);
}

.submit-btn:active {
    transform: translateY(0);
    box-shadow: 0 3px 10px rgba(74, 158, 255, 0.2);
}

.submit-btn:focus-visible {
    outline: 2px solid #4a9eff;
    outline-offset: 2px;
}

.submit-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
}

@media (max-width: 480px) {
    .container {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
        margin-bottom: 24px;
    }

    .radio-option {
        padding: 10px;
    }

    input[type="radio"] {
        width: 18px;
        height: 18px;
    }

    label {
        font-size: 14px;
    }
}

@media (prefers-reduced-motion: reduce) {
    * {
        transition: none !important;
    }
}

@media (prefers-contrast: more) {
    .container {
        border: 2px solid #555;
