        background-color: rgba(255, 255, 255, 0.1);
        border-color: #4a9eff;
    }

    .submit-btn {
        border: 2px solid #4a9eff;
    }
}

@media (forced-colors: active) {
    .container {
        border: 2px solid CanvasText;
    }

    .radio-option {
        border: 2px solid CanvasText;
    }

    .submit-btn {
        border: 2px solid ButtonText;
        forced-color-adjust: none;
    }
}
