AssistantMessageToolRequest(name='create', tool_call_id='tooluse_Uqj1OICeZRuMKgnOqP9VU7', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('notificationForm');
    const radios = document.querySelectorAll('input[type="radio"][name="notification-preference"]');

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const selectedValue = document.querySelector('input[type="radio"][name="notification-preference"]:checked');

        if (!selectedValue) {
            alert('Please select a notification preference.');
            radios[0].focus();
            return;
        }

        alert(`Preferences saved! You selected: ${selectedValue.nextElementSibling.textContent}`);
        form.reset();
    });

    radios.forEach((radio) => {
        radio.addEventListener('change', () => {
            radios.forEach((r) => {
                r.parentElement.classList.remove('selected');
            });
            radio.parentElement.classList.add('selected');
        });
    });
});
